style.css:
@-moz-document domain("rewards.bing.com") {
/* ==========[ ENCABEZADO ]========== */

/* Todo acerca del header arriba */
.l_header_container, #rewards-header, #site-header, #user-warning {
	background: #1b1a19 !important;
    border-bottom: 1.5px solid #686868; /* borde sutil para separar del contenido */
}

/* "Microsoft | Rewards" y otros enlaces del header */
.l_header_title, .other_sites, #redirect_info_link, .amc_link {
    color: #f0f0f0 !important; /* Un color de texto claro para que sea legible */
}

/* ==========[ MENÚ DESPLEGABLE DE USUARIO ]========== */

/* Fondo del menú desplegable de la cuenta */
#mectrl_popup{
  background-color: #2a2a2a !important;
  border: 2px solid #444;
}

 .ms-Callout-main, .mectrl_accountInfo, .mectrl_accountDetails {
    background-color: #2a2a2a !important;
}

/* Nombre de usuario y correo en el desplegable */
.mectrl_name, .mectrl_truncate {
    color: #f0f0f0 !important;
}

/* Enlaces "Mi cuenta de Microsoft" y "Cerrar sesión" */
#mectrl_viewAccount, #mectrl_body_signOut a {
    color: #4a90e2 !important; /* Un color azul para los enlaces para que destaquen */
}

/* Pequeña flecha del menú desplegable */
.ms-Callout-beak {
    background-color: #2a2a2a !important;
}

/* ==========[ BANNER DEL PERFIL ]========== */

/* Banner de usuario y puntos del usuario */
.userBannerGradient.profileBanner #rewardsBanner {
    background: 
    /* Un brillo sutil en la parte superior para dar profundidad */
    radial-gradient(ellipse at top, rgba(230, 230, 255, 0.08) 0%, transparent 50%),
    /* El gradiente principal de morado a azul oscuro */
    linear-gradient(160deg, #2c213d, #1c283d 80%) !important;
}

/* Texto del Banner */
.c-heading-2, .ng-binding, span, .c-action-trigger, .ng-scope {
	color: #f0f0f0 !important;
}

/* ==========[ BARRA DE NAVEGACIÓN ]========== */

/* Fondo de la barra de navegación (donde están los botones) */
.rewardsNavigationBar {
    background-color: #252525 !important;
    border: 1px solid #444;
}

/* Estilo para todos los botones de la barra (Ganar, Canjear, etc.) */
.rewardsNavigationBar .c-pivot a span {
    color: #b0b0b0 !important; /* Color de texto para botones inactivos */
    border-bottom: 3px solid transparent !important; /* Quitamos la línea de abajo por defecto */
}

.rewardsNavigationBar .c-pivot a:hover span {
    color: #ffffff !important; 
}

/* Estilo para el botón que está ACTIVO */
.rewardsNavigationBar .c-pivot a span.f-active {
    color: #ffffff !important; /* Texto blanco para resaltar */
    border-bottom: 3px solid #4a90e2 !important; /* Línea azul para indicar la sección activa */
}

/* esto es cuando salen cosas de bonificaciones o notificaciones random*/
#raf-top-banner {
	background: #1b1a19 !important;
}

h2.c-heading.ng-binding {
  color: #1b1a19 !important;
}

p.c-subheading.ng-binding.ng-scope {
  color: #1b1a19 !important;
  font-weight: 300;
}

/* Todo el Contenido de Rewards prácticamente */
.rewardsContent {
	background: #1b1a19 !important;
}

#rewardsAngular {
	background: #1b1a19 !important;
}

/* Cards de los botones del conjunto diario */
.min-dimension {
  background: #0D0D0C !important;
}

.c-card-content {
	background: #0D0D0C !important;
}

/* Checkbox */
.mee-icon-SkypeCircleCheck:before {
	background: #1b1a19 !important;
}

/* ==========[ PIE DE PÁGINA ]========== */

/* Primer Pie de Página*/
#site-footer {
  background: #151414 !important;
  border-top: 3px solid #444 !important;
}

.c-heading-5 {
  color: #f0f0f0 !important;
}

/* Último Pie de página */
.c-uhff-base, .c-uhff {
  background: #100F0F !important;
  border-top: 1px solid #444 !important;
}

/* ==========[ EXTRAS ]========== */

/* Ventajas de niveles de Rewards */
.c-dialog.f-flow [role=dialog] {
   background: #151414 !important;
  border: 1px solid #444 !important;
}
.benefit-cell:nth-child(2), .benefit-cell:nth-child(1) {
	 background: #151414 !important;
}

#modal-host > div:nth-child(1) {
	background: #15141483 !important; 
}

.beak.up {
  background: #15141483 !important;
}

#page-wrapper {
  background: #444 !important;
}

/* ==========[ Página de Canjes]========== */

/* Sección Principal */
.shuffle, #redeemRewards {
  background: #1b1a19 !important;
}

.c-drawer.hide-x {
  background: #100F0F !important;
  border: 2px solid #444 !important;
}

/* ==========[ Página de Estado }========== */

#rewardsStatus {
  background: #1b1a19 !important;
}

#badgeSummary {
  background: #100F0F !important;
}
#app-host {
  background: #1b1a19 !important;
}

b {
  color: #f0f0f0 !important;
}

/* ==========[ Página de Recomendar y Ganar }========== */

/* Container de "Cómo Funciona"*/
.user-edu-container{
  background: #1b1a19 !important;
}

.step-container.ng-scope {
  background: #100F0F !important;
}

/* Carta de "Paso" */
span.step-text.ng-binding {
  background: #050505 !important;
  border: 2px solid #444 !important;
}

/* Color del botón de copiado y su resuiltado */
#refUrlCopyButton, #mee-flyout-auto-0 .flyouttext {
  color: #000000 !important;
}

/* "Ganar puntos cuando tus amigos busquen" */
.referAndEarnCardContainer {
  background: #100F0F !important;
  border: 3px solid #444 !important;
}

p.highlight.ng-binding {
  color: #000000 !important;
  font-weight: 600 !important;
  }
}
